+#[inline]
+pub fn reduce_192b([m0, m1, m2, m01, m02, m12]: [[u64; 2]; 6]) -> [u64; 3] {
+	// `[u64; 2]` is itself an `Underlier` (blanket array impl), so `Underlier::xor` adds the
