-/// # Returns
-///
-/// The tweaked message hash
-pub fn hash_message(param: &[u8], nonce: &[u8], message: &[u8]) -> [u8; 32] {
-	use sha3::Digest;
-	let tweaked_message = build_message_hash(param, nonce, message);
-	sha3::Keccak256::digest(tweaked_message).into()
-}
